import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_op_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Approximate GELU function
__device__ float gelu_approx(float x) {
    const float c1 = 0.044715f;
    const float c2 = 0.7978845608f;  // sqrt(2.0 / M_PI)
    float x3 = x * x * x;
    float inner = c2 * (x + c1 * x3);
    return 0.5f * x * (1.0f + tanhf(inner));
}

__global__ void fused_operator_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int size,
    const float add_val,
    const float multiply_val
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx] + add_val;
        val = fminf(val, 0.0f);
        val = gelu_approx(val);
        val = val * multiply_val;
        output[idx] = val;
    }
}

torch::Tensor fused_operator_cuda(
    torch::Tensor input,
    float add_val,
    float multiply_val
) {
    auto output = torch::zeros_like(input);
    int size = input.numel();

    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;

    fused_operator_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size,
        add_val,
        multiply_val
    );

    return output;
}
"""

fused_op_cpp = r"torch::Tensor fused_operator_cuda(torch::Tensor input, float add_val, float multiply_val);"

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_op_cpp,
    cuda_sources=fused_op_source,
    extra_cflags=["-O3"],
    extra_ldflags=[],
    functions=["fused_operator_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that fuses several operations into a custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, add_value, multiply_value):
        super().__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride=stride)
        self.add_value = add_value
        self.multiply_value = multiply_value

    def forward(self, x):
        x = self.conv_transpose(x)
        x = fused_ops.fused_operator_cuda(x, self.add_value, self.multiply_value)
        return x
